-- Generated by model/lib/sql/generate.mjs. Loads IMPORT Standard Cost from cells/IMPORT Standard Cost.csv in the folder of input cells. Two rows for one cell add up.
INSERT OR REPLACE INTO "IMPORT Standard Cost" SELECT coalesce(k0."SKU", error('cells name a member SKU does not have: ' || c."SKU")), coalesce(k1."Years", error('cells name a member Years does not have: ' || c."Years")), sum(c.value::DOUBLE)
FROM read_csv('cells/IMPORT Standard Cost.csv', header = true, all_varchar = true) c LEFT JOIN "dim SKU" k0 ON k0.name = c."SKU" LEFT JOIN "dim Years" k1 ON k1.name = c."Years"
GROUP BY ALL;
